mapper.select:
SELECT A.warehouse_id AS "warehouseId" /*창고 ID*/ , A.warehouse_cd AS "warehouseCd" /*창고코드*/ , A.warehouse_nm AS "warehouseNm" /*창고명*/ , A.warehouse_type AS "warehouseType" /*창고유형*/ , A.default_yn AS "defaultYn" /*기본창고 여부*/ , A.remark AS "remark" /*설명*/ , A.sort_seq AS "sortSeq" /*정렬순서*/ , (SELECT COUNT(*) FROM materials M WHERE M.warehouse_cd = A.warehouse_cd) AS "materialCount" /*두고 있는 원재료 수*/ , A.use_yn AS "useYn" /*사용여부(상태)*/ , A.reg_user_id AS "regUserId" /*등록자 사번*/ , COALESCE(B.name, A.reg_user_id) AS "regUserNm" /*등록자 이름*/ , TO_CHAR(A.reg_dt, 'YYYY-MM-DD HH24:MI:SS') AS "regDt" /*등록일시*/ , A.upd_user_id AS "updUserId" /*수정자 사번*/ , COALESCE(C.name, A.upd_user_id) AS "updUserNm" /*수정자 이름*/ , TO_CHAR(A.upd_dt, 'YYYY-MM-DD HH24:MI:SS') AS "updDt" /*수정일시*/ FROM tb_warehouse A LEFT JOIN employees B ON B.id = A.reg_user_id LEFT JOIN employees C ON C.id = A.upd_user_id WHERE A.factory_code = #{factoryCode} AND A.plant_code = #{plantCode}
AND A.use_yn = 'Y'
ORDER BY A.sort_seq , A.warehouse_nm , A.warehouse_id

SELECT COUNT(*)
FROM tb_warehouse
WHERE factory_code = #{factoryCode}
  AND plant_code   = #{plantCode}
  AND use_yn       = 'Y'
  AND warehouse_nm = #{warehouseNm}

  AND warehouse_id != #{warehouseId}

SELECT COUNT(*)
FROM tb_warehouse
WHERE warehouse_cd = #{warehouseCd}

SELECT MAX(sort_seq)
FROM tb_warehouse
WHERE factory_code = #{factoryCode}
  AND plant_code   = #{plantCode}

mapper.insert:
INSERT INTO tb_warehouse (
    factory_code
  , plant_code
  , warehouse_cd
  , warehouse_nm
  , warehouse_type
  , default_yn
  , remark
  , sort_seq
  , use_yn
  , reg_dt
  , reg_user_id
)
VALUES (
    #{factoryCode}
  , #{plantCode}
  , #{warehouseCd}
  , #{warehouseNm}
  , #{warehouseType}
  , #{defaultYn}
  , #{remark, jdbcType=VARCHAR}
  , #{sortSeq}
  , #{useYn}
  , NOW()
  , #{userId, jdbcType=VARCHAR}
)

mapper.update:
UPDATE tb_warehouse
SET warehouse_nm   = #{warehouseNm}
  , warehouse_type = #{warehouseType}
  , default_yn     = #{defaultYn}
  , remark         = #{remark, jdbcType=VARCHAR}
  , use_yn         = #{useYn}
  , upd_dt         = NOW()
  , upd_user_id    = #{userId, jdbcType=VARCHAR}
WHERE warehouse_id = #{warehouseId}
  AND factory_code = #{factoryCode}
  AND plant_code   = #{plantCode}

UPDATE tb_warehouse
SET default_yn  = 'N'
  , upd_dt      = NOW()
  , upd_user_id = #{userId, jdbcType=VARCHAR}
WHERE factory_code   = #{factoryCode}
  AND plant_code     = #{plantCode}
  AND default_yn     = 'Y'

  AND warehouse_id  != #{warehouseId}

